templates.qfmt:
{{#正文}}<div class="pg skin-{{风格}}">
  <div class="tape"></div>
  <div class="stamp">{{类型}}</div>
  <div class="runner">
    <span class="kind">{{类型}}</span>
    {{#日期}}<span class="date">{{日期}}</span>{{/日期}}
  </div>
  <div class="rule"><i></i></div>
  {{#出处}}<div class="title">{{出处}}</div>{{/出处}}
  {{^出处}}<div class="title faint">选一个</div>{{/出处}}
  <div class="body">{{正文}}</div>
  <div class="quiz" id="quiz-root" data-side="front"><pre class="quiz-src">{{text:选项}}</pre></div>
  <div class="tail">· · ·</div>
</div>{{/正文}}
<script>
/* 生活选择 · 交互层
   ─────────────────────────────────────────────────────────────────
   这个文件同时是两个东西：
     1. 模板的内联源（被 install 脚本原样塞进 qfmt / afmt）
     2. node 单测的源（纯函数部分可直接 require）

   **不留第二份实现** —— 判定逻辑只写一遍。

   分层：
     纯函数区  lqParse / lqShuffle / lqJudge      不碰 DOM，可单测
     DOM 区    lqBoot                            只在浏览器里跑

   为什么打乱必须用 Fisher-Yates：
     `arr.sort(() => 0.5 - Math.random())` 的比较器不自洽，
     不同引擎的排序算法下分布不均匀，某些排列出现概率显著偏高。
     考试型卡片会反复出同一个选项顺序 —— 用户会当成模板坏了。
   ───────────────────────────────────────────────────────────────── */
(function (global) {
  'use strict';

  var MAX_OPTS = 26;
  var LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var STORE_KEY = 'lq:sel:v1';

  /* ══ 纯函数区 ══════════════════════════════════════════════════ */

  /* 解析选项块。
     行格式：  `- [x] 文本` / `- [ ] 文本`   —— `-` 后**恰好一个空格**
     指令行：  `# 不打乱`                    —— 以 # 开头，不参与渲染
     返回 mode：
       quiz     正常
       degrade  选项为空 / 没有任何 [x]  → 静默退化成普通摘录卡，不报错
       error    选项超过 26 个            → 卡片上显式提示（写卡的人要看见） */
  function lqParse(raw) {
    var out = { mode: 'quiz', opts: [], shuffle: true, reason: null };
    var lines = String(raw == null ? '' : raw).replace(/\r\n?/g, '\n').split('\n');

    for (var i = 0; i < lines.length; i++) {
      var s = lines[i].replace(/\s+$/, '');
      if (!s.trim()) continue;

      var d = /^\s*#\s*(.*)$/.exec(s);
      if (d) {
        if (/不打乱/.test(d[1])) out.shuffle = false;
        continue;
      }

      // `\s` 只吃一个字符 → `-  [x]`（两个空格）不识别，与规范一致
      var m = /^\s*-\s\[([ xX])\]\s?(.*)$/.exec(s);
      if (!m) continue;
      out.opts.push({ correct: m[1].toLowerCase() === 'x', text: m[2].trim() });
    }

    if (!out.opts.length) { out.mode = 'degrade'; out.reason = 'empty'; return out; }
    if (out.opts.length > MAX_OPTS) { out.mode = 'error'; out.reason = 'too-many'; return out; }
    if (!out.opts.some(function (o) { return o.correct; })) {
      out.mode = 'degrade'; out.reason = 'no-answer'; return out;
    }
    return out;
  }

  /* Fisher-Yates。rnd 可注入，测试才能复现。 */
  function lqShuffle(arr, rnd) {
    rnd = rnd || Math.random;
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(rnd() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  /* 判分。picked 是**原始下标**的数组（顺序无关）。
     三态：correct / missed / wrong。
     另外回一个 single（是否只有一个正确项）—— 单选题选错时，
     人的说法是「选错」，而不是「漏 1 · 多 1」那种算术描述。 */
  function lqJudge(opts, picked) {
    var marks = [], hit = 0, miss = 0, wrong = 0, nCorrect = 0;
    for (var i = 0; i < opts.length; i++) {
      if (opts[i].correct) nCorrect++;
      var sel = picked.indexOf(i) >= 0;
      var m;
      if (opts[i].correct && sel) { m = 'hit'; hit++; }
      else if (opts[i].correct) { m = 'miss'; miss++; }
      else if (sel) { m = 'wrong'; wrong++; }
      else { m = 'idle'; }
      marks.push(m);
    }
    var verdict = (miss === 0 && wrong === 0) ? 'correct'
      : (wrong > 0) ? 'wrong' : 'missed';
    return {
      marks: marks, verdict: verdict,
      hit: hit, miss: miss, wrong: wrong, single: nCorrect === 1
    };
  }

  function lqVerdictLabel(r) {
    if (r.verdict === 'correct') return '全对';
    if (r.single && r.miss > 0) return '选错';          // 单选没选中那个对的
    if (r.miss > 0 && r.wrong > 0) return '漏 ' + r.miss + ' · 多 ' + r.wrong;
    if (r.miss > 0) return '漏选 ' + r.miss;
    return '多选 ' + r.wrong;                            // 单选里多点了，也走这里
  }

  /* 是不是「单选答错」。
     单选只能选一个，所以「没选中正确答案」就是选错了，不是漏选。
     多选里「漏」是真漏，不能混用 —— 真机反馈（2026-09-18）：
     单选答错时正确答案标「漏」，用户读不懂。 */
  function lqIsSingleWrong(r) {
    return !!(r && r.single && r.miss > 0 && r.wrong > 0);
  }

  /* 对照行文案：把「你选 C · 答案 B」写出来。
     letterOf(i) 由 DOM 层给 —— 打乱后显示位置 ≠ 原始下标，
     要说用户看见的那个字母。
     只在单选答错时有值：多选的「漏 2 · 多 1」已经说清楚了。 */
  function lqEcho(r, letterOf) {
    if (!lqIsSingleWrong(r)) return '';
    var yours = [], rights = [];
    r.marks.forEach(function (m, i) {
      if (m === 'wrong') yours.push(letterOf(i));
      else if (m === 'miss') rights.push(letterOf(i));
    });
    if (!yours.length || !rights.length) return '';
    return '你选 ' + yours.join('、') + ' · 答案 ' + rights.join('、');
  }

  function lqLetter(i) {
    return i >= 0 && i < MAX_OPTS ? LETTERS.charAt(i) : '?';
  }

  function lqCorrectPicked(opts) {
    var a = [];
    for (var i = 0; i < opts.length; i++) if (opts[i].correct) a.push(i);
    return a;
  }

  /* ══ DOM 区 ════════════════════════════════════════════════════ */

  function lqBoot(doc) {
    var root = doc.getElementById('quiz-root');
    if (!root) return;

    // 先立旗：CSS 里 `.quiz:not([data-ready]) .quiz-src{display:block}` 是安全网。
    // 万一这段 JS 根本没跑起来，选项源码会以纯文本露出来 ——
    // 难看，但总比「选项整块消失、卡片只剩题干」强。
    root.setAttribute('data-ready', '1');

    var isFront = (root.getAttribute('data-side') || 'front') === 'front';
    var srcEl = root.querySelector('.quiz-src');
    var parsed = lqParse(srcEl ? (srcEl.textContent || '') : '');

    // 空 / 没有正确答案 → 静默降级：把交互区整块拿掉，卡片变回普通摘录卡
    if (parsed.mode === 'degrade') { root.parentNode.removeChild(root); return; }
    if (parsed.mode === 'error') {
      root.innerHTML = '<div class="quiz-warn">选项超过 ' + MAX_OPTS +
        ' 个，无法生成 A. B. C. 前缀 —— 这张卡没有按选择题渲染。</div>';
      return;
    }

    var opts = parsed.opts;
    var all = opts.map(function (_, i) { return i; });

    var list = doc.createElement('div'); list.className = 'quiz-list';
    var foot = doc.createElement('div'); foot.className = 'quiz-foot';
    var countEl = doc.createElement('span'); countEl.className = 'quiz-count';
    var echoEl = doc.createElement('span'); echoEl.className = 'quiz-echo';
    foot.appendChild(countEl); foot.appendChild(echoEl);
    root.appendChild(list); root.appendChild(foot);

    var order, picked, judged = false, snapshot = null, hasSel;

    if (isFront) {
      order = parsed.shuffle ? lqShuffle(all) : all.slice();
      picked = [];
      hasSel = true;
      // 正面永远重置。一次只显示一张卡，所以单键就够，不必按卡 id 分键。
      try { global.sessionStorage.removeItem(STORE_KEY); } catch (e) { /* 没存储也不影响正面 */ }
    } else {
      // 背面恢复**原始顺序** —— 规范第 7 条：翻面后不能还保持打乱，
      // 否则用户找不到刚才看的那个选项。
      order = all.slice();
      var saved = null;
      try { saved = JSON.parse(global.sessionStorage.getItem(STORE_KEY) || 'null'); } catch (e) { saved = null; }
      hasSel = !!(saved && Object.prototype.toString.call(saved.picked) === '[object Array]');
      picked = hasSel
        ? saved.picked.filter(function (i) { return i >= 0 && i < opts.length; })
        : [];
      judged = hasSel;
    }

    // 背面没拿到选择时，把「正确答案」当成选择来算 —— 只是为了把正确项标绿。
    // 判定文字会换成「正确答案」，绝不编造「你漏选了」。
    var judgePicked = (!isFront && !hasSel) ? lqCorrectPicked(opts) : picked;

    // ── 建行 ──────────────────────────────────────────────────
    var rows = [], byOrig = {};
    order.forEach(function (origIdx, pos) {
      var el = doc.createElement('div');
      el.className = 'quiz-opt';
      el.setAttribute('role', 'button');
      el.setAttribute('tabindex', '0');
      var key = doc.createElement('span');
      key.className = 'quiz-key'; key.textContent = lqLetter(pos) + '.';
      var txt = doc.createElement('span');
      txt.className = 'quiz-txt'; txt.textContent = opts[origIdx].text;
      var mark = doc.createElement('span');
      mark.className = 'quiz-mark';
      el.appendChild(key); el.appendChild(txt); el.appendChild(mark);
      list.appendChild(el);
      // pos 是**显示位置**（打乱后的第几位）—— 对照行要说「你选 C」，
      // 得用用户看见的那个字母，不是原始下标。
      var row = { el: el, orig: origIdx, mark: mark, pos: pos };
      rows.push(row); byOrig[origIdx] = row;
    });

    function has(i) { return picked.indexOf(i) >= 0; }

    function togglePick(i) {
      var at = picked.indexOf(i);
      if (at >= 0) picked.splice(at, 1); else picked.push(i);
      byOrig[i].el.classList.remove('is-excluded');   // 重新选它 = 撤销排除
      paint();
    }
    function toggleExclude(i) {
      byOrig[i].el.classList.toggle('is-excluded');
      paint();
    }
    function save() {
      try { global.sessionStorage.setItem(STORE_KEY, JSON.stringify({ picked: picked })); }
      catch (e) { /* 存不下就存不下，背面退化成「只标正确答案」 */ }
    }

    // ── 上色 ──────────────────────────────────────────────────
    function paint() {
      rows.forEach(function (x) {
        x.el.classList.remove('is-picked', 'is-hit', 'is-miss', 'is-wrong', 'is-answer');
        x.mark.textContent = '';
      });
      echoEl.textContent = '';

      if (isFront && !judged) {
        rows.forEach(function (x) { x.el.classList.toggle('is-picked', has(x.orig)); });
        countEl.textContent = picked.length ? '已选 ' + picked.length : '点选项作答';
        countEl.className = 'quiz-count';
        return;
      }

      var r = lqJudge(opts, judgePicked);

      /* 单选答错 ≠ 漏选。
         单选只能选一个，不存在「漏了哪个」—— 用户是**选错了**。
         真机反馈（2026-09-18）：正确答案那行写「漏」，用户看不懂，
         感觉只是「答案跳到了 B」。所以这里换一套说法：
           正确答案 → 绿 + 「答案」
           你选的那个 → 红 + 删除线 + 「你选」
         多选题没有这个问题，「漏」是多选里的正确说法，保持原样。 */
      var singleWrong = lqIsSingleWrong(r);

      r.marks.forEach(function (m, i) {
        var x = byOrig[i];
        if (!x) return;
        if (m === 'hit') { x.el.classList.add('is-hit'); x.mark.textContent = '✓'; }
        else if (m === 'miss') {
          if (singleWrong) { x.el.classList.add('is-hit', 'is-answer'); x.mark.textContent = '答案'; }
          else { x.el.classList.add('is-miss'); x.mark.textContent = '漏'; }
        }
        else if (m === 'wrong') {
          x.el.classList.add('is-wrong');
          x.mark.textContent = singleWrong ? '你选' : '✗';
        }
      });
      if (isFront) rows.forEach(function (x) { x.el.classList.toggle('is-picked', has(x.orig)); });

      if (!hasSel) {
        countEl.textContent = '正确答案';
        countEl.className = 'quiz-count is-reveal';
      } else {
        countEl.textContent = lqVerdictLabel(r);
        countEl.className = 'quiz-count is-' + r.verdict;

        // 对照行：把「你选 C · 答案 B」摆出来，别让人自己回忆。
        // 用 pos（显示位置）取字母，不用 orig —— 用户看的是打乱后的 A/B/C/D。
        echoEl.textContent = lqEcho(r, function (i) {
          var x = byOrig[i];
          return lqLetter(x ? x.pos : -1);
        });
      }
    }

    // ── 交互（只在正面） ──────────────────────────────────────
    if (isFront) {
      rows.forEach(function (x) {
        x.el.addEventListener('click', function (e) {
          if (judged) return;
          // detail===2 是双击的第二下：先把第一下改过的选择还原，再当「排除法」处理
          if (e.detail >= 2) {
            if (snapshot) { if (!has(x.orig)) picked.push(x.orig); }
            else { var at = picked.indexOf(x.orig); if (at >= 0) picked.splice(at, 1); }
            toggleExclude(x.orig);
            return;
          }
          snapshot = has(x.orig);
          togglePick(x.orig);
          save();
        });
        x.el.addEventListener('contextmenu', function (e) {
          if (judged) return;
          e.preventDefault();
          toggleExclude(x.orig);
        });
        // 触屏没有右键，长按 550ms 当排除法
        var timer = null;
        x.el.addEventListener('touchstart', function () {
          timer = global.setTimeout(function () { timer = null; if (!judged) toggleExclude(x.orig); }, 550);
        }, { passive: true });
        ['touchend', 'touchmove', 'touchcancel'].forEach(function (ev) {
          x.el.addEventListener(ev, function () {
            if (timer) { global.clearTimeout(timer); timer = null; }
          }, { passive: true });
        });
      });

      var btn = doc.createElement('button');
      btn.type = 'button';
      btn.className = 'quiz-btn';
      btn.textContent = '对答案';
      btn.addEventListener('click', function () {
        if (judged) {                    // 再看一遍：清空重来
          judged = false; picked = [];
          rows.forEach(function (x) { x.el.classList.remove('is-excluded'); });
          btn.textContent = '对答案';
        } else {
          if (!picked.length) return;
          judged = true;
          btn.textContent = '再看一遍';
        }
        paint(); save();
      });
      foot.appendChild(btn);

      // 数字键直选（1-9 → 第 1-9 项，0 → 第 10 项）。
      // **不抢 Enter / 空格** —— 那是 Anki 自己的「显示答案」，抢了会把流程打断。
      doc.addEventListener('keydown', function (e) {
        if (judged || e.ctrlKey || e.metaKey || e.altKey) return;
        var tag = ((e.target && e.target.tagName) || '').toLowerCase();
        if (tag === 'input' || tag === 'textarea') return;
        var n = /^[0-9]$/.test(e.key) ? (e.key === '0' ? 9 : parseInt(e.key, 10) - 1) : -1;
        if (n < 0 || n >= rows.length) return;
        e.preventDefault();
        togglePick(rows[n].orig);
        save();
      });
    }

    paint();
  }

  function lqReady(doc) {
    // 脚本就贴在 #quiz-root 后面，解析到这里时那个节点已经在了 ——
    // 直接跑，不等 DOMContentLoaded。等了会先画出一次源码（闪一下）。
    if (doc.getElementById('quiz-root')) { lqBoot(doc); return; }
    if (doc.readyState === 'loading') {
      doc.addEventListener('DOMContentLoaded', function () { lqBoot(doc); });
    } else {
      lqBoot(doc);
    }
  }

  if (typeof document !== 'undefined') lqReady(document);

  var api = {
    parse: lqParse, shuffle: lqShuffle, judge: lqJudge, label: lqVerdictLabel,
    letter: lqLetter, correctPicked: lqCorrectPicked,
    isSingleWrong: lqIsSingleWrong, echo: lqEcho,
    MAX_OPTS: MAX_OPTS, STORE_KEY: STORE_KEY, boot: lqBoot
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else global.LifeQuiz = api;

})(typeof globalThis !== 'undefined' ? globalThis : this);

</script>
